    The algorithm uses a dynamic programming approach to build a table that stores
    whether certain patterns match certain parts of the text.
    """

    def dp(p_index: int, t_index: int, memo: dict) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]

        # Base case: if we've processed the entire pattern
