        # Handle '*' and '+' operators
        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
                # '*' can match zero occurrences
                match_zero = dp(p_index + 2, t_index, memo)
                # '*' can match one or more occurrences if there's a match with the current character
                match_more = first_match and dp(p_index, t_index + 1, memo)
                result = match_zero or match_more
            elif pattern[p_index + 1] == '+':
                if first_match:
                    # Move forward in the text at least once
                    result = dp(p_index, t_index + 1, memo) or dp(p_index + 2, t_index, memo)
                else:
                    result = False
        else:
            result = first_match and dp(p_index + 1, t_index + 1, memo)

        memo[(p_index, t_index)] = result
        return result

    return dp(0, 0, {})

